    public void isBlank_Test() {
        String text = "";
        TextNode node = new TextNode(text);
        assertTrue(node.isBlank());
    }

    @Test
    public void isBlank_NonBlank_Test() {
        String text = "test";
        TextNode node = new TextNode(text);
        assertFalse(node.isBlank());
    }

